57	    // ── Dashboard ────────────────────────────────────────────────
58	
59	    public async Task<ReceptionistKpiDashboardDto> GetDashboardAsync(
60	        int year,
61	        int month,
62	        string? staffId,
63	        string? selectedDateKey,
64	        bool isAdminView,
65	        CancellationToken ct = default)
66	    {
67	        var monthConfig = await GetOrCreateMonthOverrideAsync(year, month, ct);
68	        var participants = await GetReceptionistParticipantsAsync(year, month, ct);
69	
70	        var selectedStaff = ResolveSelectedReceptionist(participants, staffId);
71	        if (selectedStaff is null)
72	            throw new InvalidOperationException("No receptionist profiles are available yet.");
73	
74	        var parsedDate = ParseSelectedDate(selectedDateKey, year, month);
75	        var selectedDate = parsedDate.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture);
76	        var monthMetrics = await ComputeMonthMetricsAsync(year, month, monthConfig, participants, ct);
77	        var taskStatus = await BuildTaskStatusAsync(selectedStaff, monthConfig, selectedDate, ct);
78	        var completedTaskDays = await CountCompletedTaskDaysAsync(selectedStaff.Id!, year, month, monthConfig, ct);
79	
80	        var bonusPool = monthConfig.BonusPoolAmount;
81	        var revenuePercent = ComputeTierReward(monthMetrics.GrossRevenue, monthConfig.RevenueTiers);
82	        var packagePercent = ComputeTierReward(monthMetrics.PackageSalesCount, monthConfig.PackageSalesTiers);
83	        var reviewPercent = ComputeTierReward(monthConfig.GoogleReviewCount, monthConfig.GoogleReviewTiers);
84	        var taskPercent = completedTaskDays * Math.Max(0m, monthConfig.DailyTaskCompletionPercent);
85	        var rewardsEnabled = monthConfig.KpiEnabled;
86	        var effectiveRevenuePercent = rewardsEnabled ? revenuePercent : 0m;
87	        var effectivePackagePercent = rewardsEnabled ? packagePercent : 0m;
88	        var effectiveReviewPercent = rewardsEnabled ? reviewPercent : 0m;
89	        var effectiveTaskPercent = rewardsEnabled ? taskPercent : 0m;
90	        var rawTotalPercent = effectiveRevenuePercent + effectivePackagePercent + effectiveReviewPercent + effectiveTaskPercent;
91	        var unlockedPercent = Math.Min(100m, rawTotalPercent);
92	        var unlockedAmount = RoundVnd(bonusPool * unlockedPercent / 100m);
93	        var attendanceCommission = RoundVnd(monthMetrics.CommissionByStaff.GetValueOrDefault(selectedStaff.Id ?? "", 0m));
94	
95	        // Base salary is set per-month in payroll (StaffPayable.SalaryAmount), not on
96	        // the Staff record — so read the month's payroll row and fall back to the
97	        // Staff default only when no payroll row exists yet.
98	        var payable = await _staffPayables
99	            .Find(x => x.Year == year && x.Month == month && x.StaffName == selectedStaff.Name)
100	            .FirstOrDefaultAsync(ct);
101	        var baseSalary = payable?.SalaryAmount ?? selectedStaff.BaseSalary;
102	
103	        return new ReceptionistKpiDashboardDto
104	        {
105	            Year = year,
106	            Month = month,
107	            MonthLabel = new DateTime(year, month, 1).ToString("MMMM yyyy", CultureInfo.InvariantCulture),
108	            KpiEnabled = monthConfig.KpiEnabled,
109	            IsAdminView = isAdminView,
110	            SelectedDateKey = selectedDate,
111	            Staff = MapStaff(selectedStaff),
112	            Receptionists = participants.Select(MapStaff).ToList(),
113	            MonthConfig = new ReceptionistKpiMonthConfigDto
114	            {
115	                KpiEnabled = monthConfig.KpiEnabled,
116	                GoogleReviewCount = monthConfig.GoogleReviewCount,
117	                Note = monthConfig.Note,
118	            },
119	            BonusPoolAmount = bonusPool,
120	            TotalUnlockedPercent = unlockedPercent,
121	            TotalUnlockedAmount = unlockedAmount,
122	            AttendanceCommissionAmount = attendanceCommission,
123	            BaseSalaryAmount = baseSalary,
124	            TotalProjectedPay = baseSalary + attendanceCommission + unlockedAmount,
125	            TeamAttendanceCount = monthMetrics.AttendanceHeadcount,
126	            TeamAttendanceCommissionPool = monthMetrics.AttendanceCommissionPool,
127	            Categories = BuildCategories(
128	                monthConfig,
129	                monthMetrics,
130	                completedTaskDays,
131	                bonusPool,
132	                effectiveRevenuePercent,
133	                effectivePackagePercent,
134	                effectiveReviewPercent,
135	                effectiveTaskPercent,
136	                isAdminView),
137	            DailyTasks = taskStatus,
138	        };
139	    }
