143	    public async Task<ReceptionistKpiMonthConfigDto> UpsertMonthConfigAsync(
144	        UpdateReceptionistMonthConfigRequest request,
145	        CancellationToken ct = default)
146	    {
147	        if (request.Month < 1 || request.Month > 12)
148	            throw new InvalidOperationException("Month must be between 1 and 12.");
149	
150	        var row = await GetOrCreateMonthOverrideAsync(request.Year, request.Month, ct);
151	
152	        row.KpiEnabled = request.KpiEnabled;
153	        row.GoogleReviewCount = Math.Max(0, request.GoogleReviewCount);
154	        row.Note = (request.Note ?? string.Empty).Trim();
155	        row.UpdatedAt = DateTime.UtcNow;
156	        await _monthOverrides.ReplaceOneAsync(x => x.Id == row.Id, row, cancellationToken: ct);
157	
158	        return new ReceptionistKpiMonthConfigDto
159	        {
160	            KpiEnabled = row.KpiEnabled,
161	            GoogleReviewCount = row.GoogleReviewCount,
162	            Note = row.Note,
163	        };
164	    }
