168	    public async Task<ReceptionistKpiMonthSettingsDto> GetMonthSettingsAsync(int year, int month, CancellationToken ct = default)
169	    {
170	        if (month < 1 || month > 12)
171	            throw new InvalidOperationException("Month must be between 1 and 12.");
172	        var (row, seeded) = await ResolveMonthOverrideAsync(year, month, ct);
173	        var dto = MapSettings(row);
174	        dto.CarriedForward = seeded;
175	        return dto;
176	    }
