178	    public async Task<ReceptionistKpiMonthSettingsDto> UpsertMonthSettingsAsync(
179	        UpdateReceptionistMonthSettingsRequest request,
180	        CancellationToken ct = default)
181	    {
182	        if (request.Month < 1 || request.Month > 12)
183	            throw new InvalidOperationException("Month must be between 1 and 12.");
184	
185	        var (row, _) = await ResolveMonthOverrideAsync(request.Year, request.Month, ct);
186	
187	        row.KpiEnabled = request.KpiEnabled;
188	        row.BonusPoolAmount = Math.Max(0m, request.BonusPoolAmount);
189	        row.DailyTaskCompletionPercent = Math.Max(0m, request.DailyTaskCompletionPercent);
190	        row.AttendanceCommissionPerHead = Math.Max(0m, request.AttendanceCommissionPerHead);
191	        row.AttendanceSplitMode = string.IsNullOrWhiteSpace(request.AttendanceSplitMode) ? "EQUAL_ACTIVE" : request.AttendanceSplitMode.Trim();
192	        row.GoogleReviewCount = Math.Max(0, request.GoogleReviewCount);
193	        row.Note = (request.Note ?? string.Empty).Trim();
194	        row.DailyTasks = MapTasks(request.DailyTasks);
195	        row.RevenueTiers = MapTiers(request.RevenueTiers);
196	        row.PackageSalesTiers = MapTiers(request.PackageSalesTiers);
197	        row.GoogleReviewTiers = MapTiers(request.GoogleReviewTiers);
198	        row.ConfigInitialized = true;
199	        row.UpdatedAt = DateTime.UtcNow;
200	
201	        await _monthOverrides.ReplaceOneAsync(x => x.Id == row.Id, row, cancellationToken: ct);
202	        return MapSettings(row);
203	    }
