207	    public async Task<List<ReceptionistCustomTaskDto>> GetCustomTasksAsync(string dateKey, CancellationToken ct = default)
208	    {
209	        if (!DateOnly.TryParseExact(dateKey, "yyyy-MM-dd", CultureInfo.InvariantCulture, DateTimeStyles.None, out _))
210	            throw new InvalidOperationException("Date must be in yyyy-MM-dd format.");
211	        var rows = await _customTasks.Find(x => x.DateKey == dateKey).SortBy(x => x.CreatedAt).ToListAsync(ct);
212	        return rows.Select(x => new ReceptionistCustomTaskDto { Id = x.Id!, DateKey = x.DateKey, Name = x.Name }).ToList();
213	    }
