215	    public async Task<ReceptionistCustomTaskDto> AddCustomTaskAsync(AddReceptionistCustomTaskRequest request, CancellationToken ct = default)
216	    {
217	        if (!DateOnly.TryParseExact(request.DateKey, "yyyy-MM-dd", CultureInfo.InvariantCulture, DateTimeStyles.None, out var parsed))
218	            throw new InvalidOperationException("Date must be in yyyy-MM-dd format.");
219	        var name = (request.Name ?? string.Empty).Trim();
220	        if (string.IsNullOrWhiteSpace(name))
221	            throw new InvalidOperationException("Task name is required.");
222	
223	        var row = new ReceptionistDailyCustomTask
224	        {
225	            DateKey = request.DateKey,
226	            Year = parsed.Year,
227	            Month = parsed.Month,
228	            Name = name,
229	            CreatedAt = DateTime.UtcNow,
230	        };
231	        await _customTasks.InsertOneAsync(row, cancellationToken: ct);
232	        return new ReceptionistCustomTaskDto { Id = row.Id!, DateKey = row.DateKey, Name = row.Name };
233	    }
