241	    // ── Task log ─────────────────────────────────────────────────
242	
243	    public async Task<List<string>> UpdateDailyTaskLogAsync(
244	        string staffId,
245	        string dateKey,
246	        IEnumerable<string> completedTaskIds,
247	        CancellationToken ct = default)
248	    {
249	        if (string.IsNullOrWhiteSpace(staffId))
250	            throw new InvalidOperationException("Receptionist staff id is required.");
251	
252	        if (!DateOnly.TryParseExact(dateKey, "yyyy-MM-dd", CultureInfo.InvariantCulture, DateTimeStyles.None, out var parsedDate))
253	            throw new InvalidOperationException("Date must be in yyyy-MM-dd format.");
254	
255	        var staff = await _staff.Find(s => s.Id == staffId && s.Role == "RECEPTIONIST").FirstOrDefaultAsync(ct)
256	            ?? throw new InvalidOperationException("Receptionist profile not found.");
257	
258	        var monthConfig = await GetOrCreateMonthOverrideAsync(parsedDate.Year, parsedDate.Month, ct);
259	        var allowedTaskIds = monthConfig.DailyTasks
260	            .Where(t => t.IsActive && !string.IsNullOrWhiteSpace(t.Id))
261	            .Select(t => t.Id)
262	            .ToHashSet(StringComparer.OrdinalIgnoreCase);
263	
264	        // Custom tasks for this specific date are also valid completable items.
265	        var customIds = await _customTasks.Find(x => x.DateKey == dateKey).Project(x => x.Id!).ToListAsync(ct);
266	        foreach (var cid in customIds) allowedTaskIds.Add(cid);
267	
268	        var filtered = completedTaskIds
269	            .Where(id => !string.IsNullOrWhiteSpace(id) && allowedTaskIds.Contains(id))
270	            .Distinct(StringComparer.OrdinalIgnoreCase)
271	            .ToList();
272	
273	        var existing = await _taskLogs
274	            .Find(x => x.StaffId == staffId && x.DateKey == dateKey)
275	            .FirstOrDefaultAsync(ct);
276	
277	        var row = existing ?? new ReceptionistDailyTaskLog
278	        {
279	            StaffId = staffId,
280	            StaffNameSnapshot = staff.Name,
281	            DateKey = dateKey,
282	            Year = parsedDate.Year,
283	            Month = parsedDate.Month,
284	            CreatedAt = DateTime.UtcNow,
285	        };
286	
287	        row.StaffNameSnapshot = staff.Name;
288	        row.CompletedTaskIds = filtered;
289	        row.UpdatedAt = DateTime.UtcNow;
290	
291	        if (existing is null)
292	            await _taskLogs.InsertOneAsync(row, cancellationToken: ct);
293	        else
294	            await _taskLogs.ReplaceOneAsync(x => x.Id == existing.Id, row, cancellationToken: ct);
295	
296	        return filtered;
297	    }
