299	    // ── Payables ─────────────────────────────────────────────────
300	
301	    public async Task ApplyReceptionistCompToPayablesAsync(int year, int month, CancellationToken ct = default)
302	    {
303	        var monthConfig = await GetOrCreateMonthOverrideAsync(year, month, ct);
304	        var participants = await GetReceptionistParticipantsAsync(year, month, ct);
305	        if (participants.Count == 0)
306	            return;
307	
308	        var metrics = await ComputeMonthMetricsAsync(year, month, monthConfig, participants, ct);
309	        var bonusPool = monthConfig.BonusPoolAmount;
310	        var revenuePercent = ComputeTierReward(metrics.GrossRevenue, monthConfig.RevenueTiers);
311	        var packagePercent = ComputeTierReward(metrics.PackageSalesCount, monthConfig.PackageSalesTiers);
312	        var reviewPercent = ComputeTierReward(monthConfig.GoogleReviewCount, monthConfig.GoogleReviewTiers);
313	
314	        var existingRows = await _staffPayables
315	            .Find(x => x.Year == year && x.Month == month)
316	            .ToListAsync(ct);
317	        var existingByName = existingRows.ToDictionary(x => x.StaffName.Trim(), x => x, StringComparer.OrdinalIgnoreCase);
318	
319	        foreach (var receptionist in participants)
320	        {
321	            var completedTaskDays = await CountCompletedTaskDaysAsync(receptionist.Id!, year, month, monthConfig, ct);
322	            var taskPercent = completedTaskDays * Math.Max(0m, monthConfig.DailyTaskCompletionPercent);
323	            var unlockedPercent = monthConfig.KpiEnabled
324	                ? Math.Min(100m, revenuePercent + packagePercent + reviewPercent + taskPercent)
325	                : 0m;
326	            var kpiBonus = RoundVnd(bonusPool * unlockedPercent / 100m);
327	            var attendanceCommission = RoundVnd(metrics.CommissionByStaff.GetValueOrDefault(receptionist.Id ?? "", 0m));
328	
329	            existingByName.TryGetValue(receptionist.Name.Trim(), out var prior);
330	
331	            var priorReceptionistCommission = prior?.ReceptionistAttendanceCommissionAmount ?? 0m;
332	            var priorReceptionistBonus = prior?.ReceptionistKpiBonusAmount ?? 0m;
333	            var preservedOtherCommission = (prior?.CommissionAmount ?? 0m) - priorReceptionistCommission;
334	            var preservedOtherBonus = (prior?.BonusAmount ?? 0m) - priorReceptionistBonus;
335	
336	            var row = new StaffPayable
337	            {
338	                Id = prior?.Id,
339	                StaffName = receptionist.Name.Trim(),
340	                Year = year,
341	                Month = month,
342	                SalaryAmount = receptionist.BaseSalary,
343	                ReimbursementAmount = prior?.ReimbursementAmount ?? 0m,
344	                CommissionAmount = preservedOtherCommission + attendanceCommission,
345	                BonusAmount = preservedOtherBonus + kpiBonus,
346	                ReceptionistAttendanceCommissionAmount = attendanceCommission,
347	                ReceptionistKpiBonusAmount = kpiBonus,
348	                PaidStatus = prior?.PaidStatus ?? "PENDING",
349	                PaidAt = prior?.PaidAt,
350	                CreatedAt = prior?.CreatedAt ?? DateTime.UtcNow,
351	                UpdatedAt = DateTime.UtcNow,
352	            };
353	
354	            row.TotalPayable =
355	                row.SalaryAmount +
356	                row.ReimbursementAmount +
357	                row.CommissionAmount +
358	                row.BonusAmount;
359	
360	            if (prior is null)
361	                await _staffPayables.InsertOneAsync(row, cancellationToken: ct);
362	            else
363	                await _staffPayables.ReplaceOneAsync(x => x.Id == prior.Id, row, cancellationToken: ct);
364	        }
365	    }
