367	    private async Task<List<Staff>> GetReceptionistParticipantsAsync(int year, int month, CancellationToken ct)
368	    {
369	        var monthLogs = await _taskLogs
370	            .Find(x => x.Year == year && x.Month == month)
371	            .Project(x => x.StaffId)
372	            .ToListAsync(ct);
373	        var monthPayables = await _staffPayables
374	            .Find(x => x.Year == year && x.Month == month)
375	            .Project(x => x.StaffName)
376	            .ToListAsync(ct);
377	
378	        var rows = await _staff
379	            .Find(x => x.Role == "RECEPTIONIST" && (x.IsActive || monthLogs.Contains(x.Id!) || monthPayables.Contains(x.Name)))
380	            .SortBy(x => x.Name)
381	            .ToListAsync(ct);
382	
383	        // Exclude anyone hired after this month — no pay before their start date.
384	        var monthEnd = new DateTime(year, month, 1, 0, 0, 0, DateTimeKind.Utc).AddMonths(1).AddTicks(-1);
385	        rows = rows.Where(x => !x.EmploymentStartDate.HasValue || x.EmploymentStartDate.Value <= monthEnd).ToList();
386	
387	        return rows;
388	    }
