390	    // ── Month override resolution (seed + auto-carry-forward) ────
391	
392	    private async Task<ReceptionistKpiMonthOverride> GetOrCreateMonthOverrideAsync(int year, int month, CancellationToken ct)
393	        => (await ResolveMonthOverrideAsync(year, month, ct)).row;
394	
395	    /// <summary>
396	    /// Returns the month's config row, creating/seeding it if needed. A brand-new month
397	    /// (or a legacy row that predates per-month config) inherits its config from the most
398	    /// recent prior initialised month, or from the global defaults if none exists. The
399	    /// <c>seeded</c> flag is true when this call performed that inheritance (so callers can
400	    /// tell the user "carried forward from last month").
401	    /// </summary>
402	    private async Task<(ReceptionistKpiMonthOverride row, bool seeded)> ResolveMonthOverrideAsync(int year, int month, CancellationToken ct)
403	    {
404	        var existing = await _monthOverrides
405	            .Find(x => x.Year == year && x.Month == month)
406	            .FirstOrDefaultAsync(ct);
407	
408	        if (existing is not null && existing.ConfigInitialized)
409	            return (existing, false);
410	
411	        var seedSource = await FindSeedConfigAsync(year, month, ct);
412	
413	        var row = existing ?? new ReceptionistKpiMonthOverride
414	        {
415	            Year = year,
416	            Month = month,
417	            KpiEnabled = true,
418	            GoogleReviewCount = 0,
419	            Note = string.Empty,
420	            CreatedAt = DateTime.UtcNow,
421	        };
422	
423	        ApplySeedConfig(row, seedSource);
424	        row.ConfigInitialized = true;
425	        row.UpdatedAt = DateTime.UtcNow;
426	
427	        if (existing is null)
428	            await _monthOverrides.InsertOneAsync(row, cancellationToken: ct);
429	        else
430	            await _monthOverrides.ReplaceOneAsync(x => x.Id == row.Id, row, cancellationToken: ct);
431	
432	        return (row, true);
433	    }
434	
435	    /// <summary>Most recent initialised month strictly before (year, month), or null.</summary>
436	    private async Task<ReceptionistKpiMonthOverride?> FindSeedConfigAsync(int year, int month, CancellationToken ct)
437	    {
438	        var target = year * 12 + (month - 1);
439	        var all = await _monthOverrides.Find(x => x.ConfigInitialized).ToListAsync(ct);
440	        return all
441	            .Where(x => x.Year * 12 + (x.Month - 1) < target)
442	            .OrderByDescending(x => x.Year * 12 + (x.Month - 1))
443	            .FirstOrDefault();
444	    }
445	
446	    /// <summary>Copy config from a prior month (or global settings if none) onto <paramref name="row"/>.</summary>
447	    private void ApplySeedConfig(ReceptionistKpiMonthOverride row, ReceptionistKpiMonthOverride? source)
448	    {
449	        if (source is not null)
450	        {
451	            row.BonusPoolAmount = source.BonusPoolAmount;
452	            row.DailyTaskCompletionPercent = source.DailyTaskCompletionPercent;
453	            row.AttendanceCommissionPerHead = source.AttendanceCommissionPerHead;
454	            row.AttendanceSplitMode = source.AttendanceSplitMode;
455	            row.DailyTasks = CloneTasks(source.DailyTasks);
456	            row.RevenueTiers = CloneTiers(source.RevenueTiers);
457	            row.PackageSalesTiers = CloneTiers(source.PackageSalesTiers);
458	            row.GoogleReviewTiers = CloneTiers(source.GoogleReviewTiers);
459	            return;
460	        }
461	
462	        // No prior month — seed from the global defaults (the original single config).
463	        var s = _settings.GetAsync().GetAwaiter().GetResult();
464	        row.BonusPoolAmount = s.ReceptionistKpiBonusPoolAmount;
465	        row.DailyTaskCompletionPercent = s.ReceptionistDailyTaskCompletionPercent;
466	        row.AttendanceCommissionPerHead = s.ReceptionistAttendanceCommissionPerHead;
467	        row.AttendanceSplitMode = string.IsNullOrWhiteSpace(s.ReceptionistAttendanceSplitMode) ? "EQUAL_ACTIVE" : s.ReceptionistAttendanceSplitMode;
468	        row.DailyTasks = CloneTasks(s.ReceptionistDailyTasks);
469	        row.RevenueTiers = CloneTiers(s.ReceptionistRevenueTiers);
470	        row.PackageSalesTiers = CloneTiers(s.ReceptionistPackageSalesTiers);
471	        row.GoogleReviewTiers = CloneTiers(s.ReceptionistGoogleReviewTiers);
472	    }
