596	    private async Task<int> CountCompletedTaskDaysAsync(
597	        string staffId,
598	        int year,
599	        int month,
600	        ReceptionistKpiMonthOverride monthConfig,
601	        CancellationToken ct)
602	    {
603	        var defaultTaskIds = monthConfig.DailyTasks
604	            .Where(x => x.IsActive && !string.IsNullOrWhiteSpace(x.Id))
605	            .Select(x => x.Id)
606	            .ToList();
607	
608	        var logs = await _taskLogs
609	            .Find(x => x.StaffId == staffId && x.Year == year && x.Month == month)
610	            .ToListAsync(ct);
611	        if (logs.Count == 0)
612	            return 0;
613	
614	        // Custom tasks for this month, grouped by date — each day's required set is the
615	        // month's default tasks PLUS that day's custom tasks (custom tasks count).
616	        var monthCustoms = await _customTasks.Find(x => x.Year == year && x.Month == month).ToListAsync(ct);
617	        var customsByDate = monthCustoms
618	            .GroupBy(x => x.DateKey)
619	            .ToDictionary(g => g.Key, g => g.Select(x => x.Id!).ToList());
620	
621	        var completedDays = 0;
622	        foreach (var log in logs)
623	        {
624	            var required = new HashSet<string>(defaultTaskIds, StringComparer.OrdinalIgnoreCase);
625	            if (customsByDate.TryGetValue(log.DateKey, out var customIds))
626	                foreach (var cid in customIds) required.Add(cid);
627	
628	            if (required.Count == 0)
629	                continue; // nothing to complete that day → doesn't earn the daily reward
630	
631	            var done = log.CompletedTaskIds.ToHashSet(StringComparer.OrdinalIgnoreCase);
632	            if (required.All(done.Contains))
633	                completedDays++;
634	        }
635	
636	        return completedDays;
637	    }
