641	    private async Task<ReceptionistMonthMetrics> ComputeMonthMetricsAsync(
642	        int year,
643	        int month,
644	        ReceptionistKpiMonthOverride monthConfig,
645	        List<Staff> participants,
646	        CancellationToken ct)
647	    {
648	        var start = new DateTime(year, month, 1, 0, 0, 0, DateTimeKind.Utc);
649	        var end = start.AddMonths(1);
650	
651	        var paidInvoices = await _invoices
652	            .Find(x => x.Status == "PAID" && x.IssueDate >= start && x.IssueDate < end)
653	            .ToListAsync(ct);
654	
655	        var grossRevenue = paidInvoices.Sum(x => x.TotalNet);
656	        var packageSales = await CountPackageSalesAsync(paidInvoices, ct);
657	
658	        // Completed sessions this month (with their local start time), and the paid
659	        // headcount per session.
660	        var sessions = await _sessions
661	            .Find(x => x.Status == "COMPLETED" && x.StartTime >= start && x.StartTime < end && !x.IsFreelance)
662	            .Project(x => new { x.Id, x.StartTime })
663	            .ToListAsync(ct);
664	
665	        var headBySession = new Dictionary<string, int>();
666	        decimal attendanceHeadcount = 0m;
667	        if (sessions.Count > 0)
668	        {
669	            var sessionIds = sessions.Select(s => s.Id).ToList();
670	            var attendanceRows = await _attendances
671	                .Find(Builders<Attendance>.Filter.And(
672	                    Builders<Attendance>.Filter.In(x => x.CalendarSessionId, sessionIds),
673	                    Builders<Attendance>.Filter.In(x => x.Status, CountingAttendanceStatuses)))
674	                .ToListAsync(ct);
675	
676	            foreach (var a in attendanceRows)
677	            {
678	                if (string.IsNullOrWhiteSpace(a.CalendarSessionId)) continue;
679	                headBySession[a.CalendarSessionId] = headBySession.GetValueOrDefault(a.CalendarSessionId) + Math.Max(1, a.Quantity);
680	            }
681	            attendanceHeadcount = headBySession.Values.Sum();
682	        }
683	
684	        // Attendance commission is SHIFT-BASED: for each class, only receptionists who
685	        // were on shift (within a work window, excluding lunch breaks) at the class's
686	        // local start time earn the per-head commission for that class's attendees,
687	        // split equally between them. If nobody was on shift, that class pays nothing.
688	        var perHead = Math.Max(0m, monthConfig.AttendanceCommissionPerHead);
689	        var commissionByStaff = new Dictionary<string, decimal>();
690	        decimal distributedPool = 0m;
691	
692	        if (headBySession.Count > 0 && perHead > 0m && participants.Count > 0)
693	        {
694	            var from = new DateOnly(year, month, 1);
695	            var to = from.AddMonths(1).AddDays(-1);
696	            var occurrences = await _shifts.GetScheduleAsync(from, to, null);
697	            var receptionistIds = participants.Where(p => p.Id != null).Select(p => p.Id!).ToHashSet();
698	            var occByDate = occurrences
699	                .Where(o => receptionistIds.Contains(o.StaffId))
700	                .GroupBy(o => o.Date)
701	                .ToDictionary(g => g.Key, g => g.ToList());
702	
703	            foreach (var s in sessions)
704	            {
705	                if (!headBySession.TryGetValue(s.Id!, out var head) || head <= 0) continue;
706	                var local = StudioTime.Local(s.StartTime);
707	                var dateKey = local.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture);
708	                var minutes = local.Hour * 60 + local.Minute;
709	                if (!occByDate.TryGetValue(dateKey, out var dayOccs)) continue;
710	
711	                var covering = dayOccs
712	                    .Where(o => IsWithinShift(o, minutes))
713	                    .Select(o => o.StaffId)
714	                    .Distinct()
715	                    .ToList();
716	                if (covering.Count == 0) continue;
717	
718	                var sessionCommission = head * perHead;
719	                var perStaff = sessionCommission / covering.Count;
720	                foreach (var sid in covering)
721	                    commissionByStaff[sid] = commissionByStaff.GetValueOrDefault(sid) + perStaff;
722	                distributedPool += sessionCommission;
723	            }
724	        }
725	
726	        return new ReceptionistMonthMetrics
727	        {
728	            GrossRevenue = grossRevenue,
729	            PackageSalesCount = packageSales,
730	            AttendanceHeadcount = attendanceHeadcount,
731	            AttendanceCommissionPool = RoundVnd(distributedPool),
732	            CommissionByStaff = commissionByStaff,
733	        };
734	    }
735	
736	    /// <summary>True if <paramref name="minutes"/> (local minutes-of-day) falls inside a shift
737	    /// occurrence's work window and NOT inside one of its breaks.</summary>
738	    private static bool IsWithinShift(StaffShiftOccurrence occ, int minutes)
739	    {
740	        if (!TryMinutes(occ.StartTime, out var s) || !TryMinutes(occ.EndTime, out var e)) return false;
741	        if (minutes < s || minutes >= e) return false;
742	        foreach (var b in occ.Breaks ?? new())
743	        {
744	            if (TryMinutes(b.Open, out var bo) && TryMinutes(b.Close, out var bc)
745	                && minutes >= bo && minutes < bc)
746	                return false;
747	        }
748	        return true;
749	    }
750	
751	    private static bool TryMinutes(string? hhmm, out int minutes)
752	    {
753	        minutes = 0;
754	        if (string.IsNullOrWhiteSpace(hhmm)) return false;
755	        var parts = hhmm.Split(':');
756	        if (parts.Length < 2) return false;
757	        if (!int.TryParse(parts[0], out var h) || !int.TryParse(parts[1], out var m)) return false;
758	        minutes = h * 60 + m;
759	        return true;
760	    }
