762	    private async Task<int> CountPackageSalesAsync(List<Invoice> paidInvoices, CancellationToken ct)
763	    {
764	        var legacyProductIds = paidInvoices
765	            .SelectMany(x => x.Lines)
766	            .Where(x => string.IsNullOrWhiteSpace(x.ProductTypeSnapshot) && !string.IsNullOrWhiteSpace(x.ProductId))
767	            .Select(x => x.ProductId!)
768	            .Distinct()
769	            .ToList();
770	
771	        var legacyProducts = legacyProductIds.Count == 0
772	            ? new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
773	            : (await _products.Find(x => legacyProductIds.Contains(x.Id!)).ToListAsync(ct))
774	                .ToDictionary(x => x.Id!, x => x.Type ?? string.Empty, StringComparer.OrdinalIgnoreCase);
775	
776	        return paidInvoices
777	            .SelectMany(x => x.Lines)
778	            .Count(line =>
779	            {
780	                var productType = line.ProductTypeSnapshot;
781	                if (string.IsNullOrWhiteSpace(productType) && !string.IsNullOrWhiteSpace(line.ProductId))
782	                    legacyProducts.TryGetValue(line.ProductId, out productType);
783	                return string.Equals(productType, "PACKAGE", StringComparison.OrdinalIgnoreCase);
784	            });
785	    }
