848	    private ReceptionistKpiCategoryProgressDto BuildTierCategory(
849	        string key,
850	        string label,
851	        string description,
852	        decimal currentValue,
853	        decimal unlockedPercent,
854	        decimal bonusPool,
855	        IEnumerable<ReceptionistKpiTier> tiers,
856	        string currentValueLabel,
857	        string? adminDetail,
858	        bool redactGoals)
859	    {
860	        var ordered = tiers
861	            .OrderBy(x => x.Goal)
862	            .ToList();
863	
864	        var unlockedCount = ordered.Count(x => currentValue >= x.Goal);
865	
866	        // Progress toward the NEXT unreached tier so the bar reflects real activity
867	        // even before a tier is unlocked (e.g. 29.8M of a 100M tier 1 → 30% filled).
868	        var nextTier = ordered.FirstOrDefault(t => currentValue < t.Goal);
869	        decimal progressToNext;
870	        string nextLabel;
871	        if (nextTier == null)
872	        {
873	            progressToNext = 100m;
874	            nextLabel = "All tiers reached";
875	        }
876	        else
877	        {
878	            progressToNext = nextTier.Goal > 0 ? Math.Min(100m, currentValue / nextTier.Goal * 100m) : 0m;
879	            nextLabel = redactGoals
880	                ? $"{progressToNext:N0}% to {nextTier.Label}"
881	                : $"{currentValue:N0} / {nextTier.Goal:N0} to {nextTier.Label}";
882	        }
883	
884	        var tierDtos = ordered.Select(tier => new ReceptionistKpiTierProgressDto
885	        {
886	            Id = tier.Id,
887	            Label = tier.Label,
888	            GoalLabel = redactGoals ? tier.Label : $"{tier.Goal:N0}",
889	            RewardLabel = $"+{tier.RewardPercent:N0}%",
890	            IsUnlocked = currentValue >= tier.Goal,
891	            ProgressLabel = currentValue >= tier.Goal
892	                ? "Unlocked"
893	                : redactGoals
894	                    ? $"{(tier.Goal > 0 ? Math.Min(100m, currentValue / tier.Goal * 100m) : 0m):N0}% there"
895	                    : $"{currentValue:N0} / {tier.Goal:N0}",
896	            ProgressPercent = currentValue >= tier.Goal
897	                ? 100m
898	                : tier.Goal > 0 ? Math.Min(100m, currentValue / tier.Goal * 100m) : 0m,
899	        }).ToList();
900	
901	        return new ReceptionistKpiCategoryProgressDto
902	        {
903	            Key = key,
904	            Label = label,
905	            Description = description,
906	            UnlockedPercent = unlockedPercent,
907	            UnlockedAmount = RoundVnd(bonusPool * unlockedPercent / 100m),
908	            ProgressLabel = $"{unlockedCount} / {ordered.Count} {currentValueLabel}",
909	            AdminDetail = adminDetail,
910	            ProgressToNextPercent = progressToNext,
911	            NextTierLabel = nextLabel,
912	            Tiers = tierDtos,
913	        };
914	    }
