169	    private bool TryValidate(IFormFile? file, out IActionResult? problem)
170	    {
171	        problem = null;
172	
173	        if (file is null || file.Length == 0)
174	        {
175	            problem = BadRequest(new { error = "No file uploaded" });
176	            return false;
177	        }
178	
179	        if (file.Length > _settings.MaxUploadBytes)
180	        {
181	            problem = StatusCode(StatusCodes.Status413PayloadTooLarge,
182	                new { error = $"File exceeds {_settings.MaxUploadBytes / 1_048_576} MB limit" });
183	            return false;
184	        }
185	
186	        // Content-type whitelist
187	        var ct = (file.ContentType ?? "").ToLowerInvariant();
188	        if (ct is not ("image/jpeg" or "image/jpg" or "image/png" or "image/webp" or "image/gif"))
189	        {
190	            problem = BadRequest(new { error = $"Unsupported content type '{file.ContentType}'. Use JPEG, PNG, WebP or GIF." });
191	            return false;
192	        }
193	
194	        // Magic-byte sniff (defensive: a renamed .exe should be rejected here)
195	        if (!HasImageMagicBytes(file))
196	        {
197	            problem = BadRequest(new { error = "File contents do not appear to be a valid image." });
198	            return false;
199	        }
200	
201	        return true;
202	    }
203	
204	    private static bool HasImageMagicBytes(IFormFile file)
205	    {
206	        Span<byte> buf = stackalloc byte[12];
207	        using var s = file.OpenReadStream();
208	        var read = s.Read(buf);
209	        if (read < 4) return false;
210	
211	        // JPEG  FF D8 FF
212	        if (buf[0] == 0xFF && buf[1] == 0xD8 && buf[2] == 0xFF) return true;
213	        // PNG   89 50 4E 47
214	        if (buf[0] == 0x89 && buf[1] == 0x50 && buf[2] == 0x4E && buf[3] == 0x47) return true;
215	        // GIF   47 49 46 38
216	        if (buf[0] == 0x47 && buf[1] == 0x49 && buf[2] == 0x46 && buf[3] == 0x38) return true;
217	        // WebP  52 49 46 46 …. 57 45 42 50
218	        if (read >= 12 && buf[0] == 0x52 && buf[1] == 0x49 && buf[2] == 0x46 && buf[3] == 0x46
219	            && buf[8] == 0x57 && buf[9] == 0x45 && buf[10] == 0x42 && buf[11] == 0x50) return true;
220	        return false;
221	    }
222	}
