30	    public MediaStorageService(IOptions<StorageSettings> settings, ILogger<MediaStorageService> logger)
31	    {
32	        _settings = settings.Value;
33	        _logger = logger;
34	
35	        var s3Config = new AmazonS3Config
36	        {
37	            ServiceURL = _settings.Endpoint,
38	            ForcePathStyle = _settings.ForcePathStyle,
39	            AuthenticationRegion = _settings.Region,
40	        };
