45	    /// <summary>
46	    /// Returns <c>true</c> when the configured S3 endpoint uses HTTPS.
47	    ///
48	    /// <para>
49	    /// AWSSDK.S3 v4 added a guard that rejects requests with
50	    /// <see cref="PutObjectRequest.DisablePayloadSigning"/> = true unless the
51	    /// transport is HTTPS, raising <c>AmazonClientException: "When
52	    /// DisablePayloadSigning is true, the request must be sent over HTTPS."</c>
53	    /// Our local RustFS dev stack runs on plain HTTP, so we leave payload
54	    /// signing enabled there — RustFS supports SigV4 with payload signing.
55	    /// In production (HTTPS) we keep the option to opt out of payload
56	    /// signing for endpoints that mis-handle large chunked uploads.
57	    /// </para>
58	    /// </summary>
59	    private bool IsHttpsEndpoint =>
60	        Uri.TryCreate(_settings.Endpoint, UriKind.Absolute, out var uri) &&
61	        string.Equals(uri.Scheme, Uri.UriSchemeHttps, StringComparison.OrdinalIgnoreCase);
