63	    public async Task<string> UploadImageAsync(Stream input, string key, int? maxDimensionPx = null, CancellationToken ct = default)
64	    {
65	        if (string.IsNullOrWhiteSpace(key))
66	            throw new ArgumentException("Storage key is required", nameof(key));
67	
68	        var maxDim = maxDimensionPx ?? _settings.MaxImageDimensionPx;
69	
70	        // Decode
71	        using var image = await Image.LoadAsync(input, ct);
72	
73	        // Strip EXIF for privacy + size
74	        image.Metadata.ExifProfile = null;
75	        image.Metadata.IptcProfile = null;
76	        image.Metadata.XmpProfile = null;
77	
78	        // Resize down only if needed (long-edge, preserve aspect)
79	        if (image.Width > maxDim || image.Height > maxDim)
80	        {
81	            image.Mutate(ctx => ctx.Resize(new ResizeOptions
82	            {
83	                Mode = ResizeMode.Max,
84	                Size = new Size(maxDim, maxDim),
85	                Sampler = KnownResamplers.Lanczos3,
86	            }));
87	        }
88	
89	        // Encode to WebP
90	        await using var ms = new MemoryStream();
91	        var encoder = new WebpEncoder
92	        {
93	            Quality = _settings.WebPQuality,
94	            FileFormat = WebpFileFormatType.Lossy,
95	        };
96	        await image.SaveAsync(ms, encoder, ct);
97	        ms.Position = 0;
98	
99	        // Capture the payload size before handing the stream to the SDK —
100	        // AWSSDK.S3 v4 disposes the InputStream after a successful PUT
101	        // (PutObjectRequest.AutoCloseStream defaults to true). Reading
102	        // ms.Length post-PUT throws ObjectDisposedException.
103	        var payloadBytes = ms.Length;
104	
105	        // PUT
106	        var put = new PutObjectRequest
107	        {
108	            BucketName = _settings.PublicBucket,
109	            Key = key,
110	            InputStream = ms,
111	            ContentType = "image/webp",
112	            // Only opt out of payload signing on HTTPS endpoints — see
113	            // IsHttpsEndpoint comment for context. RustFS over HTTP needs
114	            // signed payloads otherwise AWSSDK.S3 v4 refuses to send.
115	            DisablePayloadSigning = IsHttpsEndpoint,
116	            DisableDefaultChecksumValidation = true,
117	            Headers =
118	            {
119	                CacheControl = "public, max-age=31536000, immutable",
120	            },
121	        };
122	
123	        await _s3.PutObjectAsync(put, ct);
124	        _logger.LogInformation("Uploaded image to {Bucket}/{Key} ({Bytes} bytes)", _settings.PublicBucket, key, payloadBytes);
125	
126	        return key;
127	    }
