9	/**
10	 * Upload an image to a media endpoint.
11	 * @param {string} relativeUrl  e.g. "/api/media/class-image/{id}"
12	 * @param {File}   file
13	 * @returns {Promise<{url:string,key:string}>}
14	 */
15	export async function uploadImage(relativeUrl, file) {
16	  const fd = new FormData();
17	  fd.append('file', file, file.name);
18	
19	  const res = await fetch(`${API}${relativeUrl}`, {
20	    method: 'POST',
21	    headers: { 'Authorization': 'Bearer ' + getToken() },
22	    body: fd,
23	  });
24	
25	  let payload = null;
26	  try { payload = await res.json(); } catch { /* ignore */ }
27	
28	  if (!res.ok) {
29	    const msg = (payload && payload.error) || `Upload failed (HTTP ${res.status})`;
30	    throw new Error(msg);
31	  }
32	  return payload;
33	}
34	
35	/**
36	 * Remove the image at a media endpoint.
37	 */
38	export async function deleteImage(relativeUrl) {
39	  const res = await fetch(`${API}${relativeUrl}`, {
40	    method: 'DELETE',
41	    headers: { 'Authorization': 'Bearer ' + getToken() },
42	  });
43	  if (!res.ok && res.status !== 204) {
44	    let msg = `Delete failed (HTTP ${res.status})`;
45	    try { const p = await res.json(); if (p && p.error) msg = p.error; } catch { /* ignore */ }
46	    throw new Error(msg);
47	  }
48	}
