using MongoDB.Bson;
using MongoDB.Bson.Serialization.Attributes;

namespace SoulPilates.Core.Entities;

/// <summary>
/// A screenshot of a Google review that a receptionist received and uploaded,
/// attributed to that receptionist and assigned to a calendar month. The month's
/// total upload count feeds the receptionist-KPI "Google reviews" metric additively
/// (on top of the admin-entered manual count — see <see cref="ReceptionistKpiMonthOverride.GoogleReviewCount"/>).
/// Image bytes live in object storage (RustFS/S3) via <c>IMediaStorage</c>; only the
/// storage key + public URL are persisted here.
/// </summary>
public class ReviewUpload : BaseEntity
{
    /// <summary>The receptionist this review is credited to.</summary>
    [BsonRepresentation(BsonType.ObjectId)]
    public string StaffId { get; set; } = null!;

    /// <summary>Staff display name captured at upload time (survives later renames).</summary>
    public string StaffNameSnapshot { get; set; } = string.Empty;

    // ── Period the review is assigned to ─────────────────────────
    public int Year { get; set; }
    public int Month { get; set; }

    // ── Stored image (via IMediaStorage) ─────────────────────────
    /// <summary>Deterministic storage key, e.g. "review-uploads/{id}.webp".</summary>
    public string ImageKey { get; set; } = string.Empty;
    /// <summary>Absolute public URL resolved from the key.</summary>
    public string ImageUrl { get; set; } = string.Empty;

    // ── Optional metadata ────────────────────────────────────────
    public string? ReviewerName { get; set; }
    /// <summary>Optional 1–5 star rating, if the receptionist records it.</summary>
    public int? Rating { get; set; }
    public string? Notes { get; set; }

    /// <summary>The date/time the image was added (the "added-date" shown in the gallery).</summary>
    public DateTime UploadedAt { get; set; } = DateTime.UtcNow;
}

namespace SoulPilates.Core.DTOs;

/// <summary>One uploaded review image in the gallery view.</summary>
public class ReviewUploadDto
{
    public string Id { get; set; } = string.Empty;
    public string StaffId { get; set; } = string.Empty;
    public string StaffName { get; set; } = string.Empty;
    public int Year { get; set; }
    public int Month { get; set; }
    public string ImageUrl { get; set; } = string.Empty;
    public string? ReviewerName { get; set; }
    public int? Rating { get; set; }
    public string? Notes { get; set; }
    /// <summary>The date the image was added (ISO-8601, UTC).</summary>
    public DateTime UploadedAt { get; set; }
}

/// <summary>The month's gallery for one receptionist plus its running total.</summary>
public class ReviewUploadListDto
{
    public int Year { get; set; }
    public int Month { get; set; }
    public string StaffId { get; set; } = string.Empty;
    public int Count { get; set; }
    public List<ReviewUploadDto> Items { get; set; } = new();
}

using System.IO;
using SoulPilates.Core.DTOs;

namespace SoulPilates.Core.Interfaces;

/// <summary>
/// Receptionist-uploaded Google-review screenshots. Each upload is attributed to a
/// receptionist and assigned to a month; the month's count feeds the KPI "Google
/// reviews" metric additively (see <c>IReceptionistKpiService</c>).
/// </summary>
public interface IReviewUploadService
{
    /// <summary>
    /// Store an uploaded review image and record it for (staff, year, month).
    /// The stream is processed + persisted via <c>IMediaStorage</c> (WebP, EXIF-stripped).
    /// </summary>
    Task<ReviewUploadDto> AddAsync(
        string staffId,
        int year,
        int month,
        Stream imageStream,
        string? reviewerName,
        int? rating,
        string? notes,
        CancellationToken ct = default);

    /// <summary>All review uploads for one receptionist in one month, newest first.</summary>
    Task<ReviewUploadListDto> ListForStaffMonthAsync(string staffId, int year, int month, CancellationToken ct = default);

    /// <summary>
    /// Delete an upload (and its stored image). When <paramref name="requireStaffId"/> is
    /// non-null the row must belong to that receptionist (self-service delete); admins pass null.
    /// Returns false if not found or not owned.
    /// </summary>
    Task<bool> DeleteAsync(string id, string? requireStaffId, CancellationToken ct = default);

    /// <summary>Total number of uploaded reviews for a month across all receptionists (for the KPI metric).</summary>
    Task<int> CountForMonthAsync(int year, int month, CancellationToken ct = default);
}

using MongoDB.Bson;
using MongoDB.Driver;
using SoulPilates.Core.DTOs;
using SoulPilates.Core.Entities;
using SoulPilates.Core.Interfaces;
using SoulPilates.Infrastructure.Data;

namespace SoulPilates.Services;

/// <summary>
/// Receptionist-uploaded Google-review screenshots. Images go through the shared
/// <see cref="IMediaStorage"/> pipeline (decode → EXIF-strip → resize → WebP) exactly
/// like class/instructor photos; only the resulting key + URL are stored on the record.
/// </summary>
public class ReviewUploadService : IReviewUploadService
{
    private const string KeyPrefix = "review-uploads";

    private readonly IMongoCollection<ReviewUpload> _uploads;
    private readonly IMongoCollection<Staff> _staff;
    private readonly IMediaStorage _media;

    public ReviewUploadService(MongoDbContext db, IMediaStorage media)
    {
        _uploads = db.GetCollection<ReviewUpload>("ReviewUploads");
        _staff = db.GetCollection<Staff>("Staff");
        _media = media;

        // Fast lookups for the per-staff monthly gallery and the KPI monthly count.
        _uploads.Indexes.CreateOne(new CreateIndexModel<ReviewUpload>(
            Builders<ReviewUpload>.IndexKeys
                .Ascending(x => x.StaffId)
                .Ascending(x => x.Year)
                .Ascending(x => x.Month),
            new CreateIndexOptions { Name = "ix_staff_year_month" }));
        _uploads.Indexes.CreateOne(new CreateIndexModel<ReviewUpload>(
            Builders<ReviewUpload>.IndexKeys
                .Ascending(x => x.Year)
                .Ascending(x => x.Month),
            new CreateIndexOptions { Name = "ix_year_month" }));
    }

    public async Task<ReviewUploadDto> AddAsync(
        string staffId,
        int year,
        int month,
        Stream imageStream,
        string? reviewerName,
        int? rating,
        string? notes,
        CancellationToken ct = default)
    {
        if (string.IsNullOrWhiteSpace(staffId))
            throw new InvalidOperationException("Receptionist staff id is required.");
        if (month < 1 || month > 12)
            throw new InvalidOperationException("Month must be between 1 and 12.");
        if (year < 2000 || year > 2100)
            throw new InvalidOperationException("Year is out of range.");

        var staff = await _staff.Find(s => s.Id == staffId && s.Role == "RECEPTIONIST").FirstOrDefaultAsync(ct)
            ?? throw new InvalidOperationException("Receptionist profile not found.");

        // Deterministic per-record key — generate the id up front so the stored image
        // and the record share it (mirrors the media pattern for entity-owned images).
        var id = ObjectId.GenerateNewId().ToString();
        var key = $"{KeyPrefix}/{id}.webp";

        await _media.UploadImageAsync(imageStream, key, ct: ct);
        var url = _media.PublicUrlFor(key);

        var normalizedRating = rating is >= 1 and <= 5 ? rating : null;

        var row = new ReviewUpload
        {
            Id = id,
            StaffId = staffId,
            StaffNameSnapshot = staff.Name,
            Year = year,
            Month = month,
            ImageKey = key,
            ImageUrl = url,
            ReviewerName = string.IsNullOrWhiteSpace(reviewerName) ? null : reviewerName.Trim(),
            Rating = normalizedRating,
            Notes = string.IsNullOrWhiteSpace(notes) ? null : notes.Trim(),
            UploadedAt = DateTime.UtcNow,
        };

        try
        {
            await _uploads.InsertOneAsync(row, cancellationToken: ct);
        }
        catch
        {
            // Don't leave an orphaned object in storage if the DB write fails.
            await _media.DeleteAsync(key, ct);
            throw;
        }

        return Map(row);
    }

    public async Task<ReviewUploadListDto> ListForStaffMonthAsync(string staffId, int year, int month, CancellationToken ct = default)
    {
        if (string.IsNullOrWhiteSpace(staffId))
            throw new InvalidOperationException("Receptionist staff id is required.");
        if (month < 1 || month > 12)
            throw new InvalidOperationException("Month must be between 1 and 12.");

        var rows = await _uploads
            .Find(x => x.StaffId == staffId && x.Year == year && x.Month == month)
            .SortByDescending(x => x.UploadedAt)
            .ToListAsync(ct);

        return new ReviewUploadListDto
        {
            Year = year,
            Month = month,
            StaffId = staffId,
            Count = rows.Count,
            Items = rows.Select(Map).ToList(),
        };
    }

    public async Task<bool> DeleteAsync(string id, string? requireStaffId, CancellationToken ct = default)
    {
        var row = await _uploads.Find(x => x.Id == id).FirstOrDefaultAsync(ct);
        if (row is null)
            return false;
        if (!string.IsNullOrWhiteSpace(requireStaffId) && row.StaffId != requireStaffId)
            return false;

        var res = await _uploads.DeleteOneAsync(x => x.Id == id, ct);
        if (res.DeletedCount == 0)
            return false;

        if (!string.IsNullOrWhiteSpace(row.ImageKey))
            await _media.DeleteAsync(row.ImageKey, ct);
        return true;
    }

    public Task<int> CountForMonthAsync(int year, int month, CancellationToken ct = default)
        => _uploads.CountDocumentsAsync(x => x.Year == year && x.Month == month, cancellationToken: ct)
            .ContinueWith(t => (int)t.Result, ct, TaskContinuationOptions.OnlyOnRanToCompletion, TaskScheduler.Default);

    private static ReviewUploadDto Map(ReviewUpload x) => new()
    {
        Id = x.Id ?? string.Empty,
        StaffId = x.StaffId,
        StaffName = x.StaffNameSnapshot,
        Year = x.Year,
        Month = x.Month,
        ImageUrl = x.ImageUrl,
        ReviewerName = x.ReviewerName,
        Rating = x.Rating,
        Notes = x.Notes,
        UploadedAt = x.UploadedAt,
    };
}

