/// <summary>Receptionist-uploaded Google-review screenshots for the month (added to the manual count).</summary>
public int ReviewUploadCount { get; set; }
public decimal AttendanceHeadcount { get; set; }

private static decimal ComputeTierReward(decimal currentValue, IEnumerable<ReceptionistKpiTier> tiers)
    => tiers.Where(x => currentValue >= x.Goal).Sum(x => Math.Max(0m, x.RewardPercent));

/// <summary>
/// The Google-review count the tiers reward against: the admin-entered manual value
/// (<see cref="ReceptionistKpiMonthOverride.GoogleReviewCount"/>) PLUS the number of
/// receptionist-uploaded review screenshots for the month. Additive by design — with
/// zero uploads this equals the manual value, so the manager's existing manual path is
/// unchanged. The manual value remains fully editable and is never overwritten.
/// </summary>
