---
import AdminLayout from "../../layouts/AdminLayout.astro";
---

<AdminLayout title="Review Uploads" activePage="reception-reviews">
  <div class="rev-page-shell">
    <div class="rev-page-header">
      <div>
        <div class="page-title">Google Review Uploads</div>
        <div class="page-subtitle">
          Upload a screenshot of each Google review you receive. It counts toward this month's Google Reviews KPI.
        </div>
      </div>
      <div class="rev-page-actions">
        <label class="rev-action-control">
          <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
            <rect x="3" y="4" width="18" height="18" rx="2"></rect>
            <line x1="16" y1="2" x2="16" y2="6"></line>
            <line x1="8" y1="2" x2="8" y2="6"></line>
            <line x1="3" y1="10" x2="21" y2="10"></line>
          </svg>
          <input type="month" id="monthPicker" class="rev-inline-input" />
        </label>

        <label id="staffPickerWrap" class="rev-action-control" style="display:none;">
          <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
            <path d="M16 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"></path>
            <circle cx="8.5" cy="7" r="4"></circle>
          </svg>
          <select id="staffPicker" class="rev-inline-select"></select>
        </label>
      </div>
    </div>

    <div id="revBanner" class="card rev-banner-card" style="display:none;">
      <div class="card-body" id="revBannerText"></div>
    </div>

    <div class="rev-grid">
      <section class="card rev-upload-card">
        <div class="card-header">
          <div>
            <div class="card-title">Add a Review</div>
            <div class="card-subtitle">Assigned to <strong id="uploadMonthLabel">this month</strong>.</div>
          </div>
        </div>
        <div class="card-body">
          <div class="rev-dropzone" id="dropzone">
            <input type="file" id="fileInput" accept="image/png,image/jpeg,image/webp,image/gif" hidden />
            <img id="previewImg" class="rev-preview" alt="Preview" style="display:none;" />
            <div id="dropPrompt" class="rev-drop-prompt">
              <svg xmlns="http://www.w3.org/2000/svg" width="30" height="30" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6">
                <path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"></path>
                <polyline points="17 8 12 3 7 8"></polyline>
                <line x1="12" y1="3" x2="12" y2="15"></line>
              </svg>
              <span>Tap to choose a screenshot</span>
              <small>PNG, JPEG, WebP or GIF — up to 10 MB</small>
            </div>
          </div>

          <div class="form-group">
            <label class="form-label" for="reviewerNameInput">Reviewer name <span class="rev-optional">(optional)</span></label>
            <input type="text" id="reviewerNameInput" class="form-control" placeholder="e.g. Linh Nguyen" maxlength="120" />
          </div>

          <div class="form-group">
            <label class="form-label" for="ratingInput">Rating <span class="rev-optional">(optional)</span></label>
            <select id="ratingInput" class="form-control">
              <option value="">No rating</option>
              <option value="5">★★★★★ (5)</option>
              <option value="4">★★★★ (4)</option>
              <option value="3">★★★ (3)</option>
              <option value="2">★★ (2)</option>
              <option value="1">★ (1)</option>
            </select>
          </div>

          <div class="form-group">
            <label class="form-label" for="notesInput">Notes <span class="rev-optional">(optional)</span></label>
            <textarea id="notesInput" class="form-control" rows="2" maxlength="500" placeholder="Optional note"></textarea>
          </div>

          <div class="rev-upload-footer">
            <button class="btn btn-primary" type="button" id="uploadBtn" disabled>Upload Review</button>
            <span id="uploadMsg" class="rev-inline-msg success" style="display:none;">Uploaded</span>
            <span id="uploadErr" class="rev-inline-msg error" style="display:none;"></span>
          </div>
        </div>
      </section>

      <section class="card rev-gallery-card">
        <div class="card-header">
          <div>
            <div class="card-title">This Month's Reviews</div>
            <div class="card-subtitle" id="galleryMonthLabel">Loading</div>
          </div>
          <div class="rev-count-pill"><span id="galleryCount">0</span> uploaded</div>
        </div>
        <div class="card-body">
          <div id="galleryGrid" class="rev-gallery-grid"></div>
          <div id="galleryEmpty" class="rev-empty" style="display:none;">
            No reviews uploaded for this month yet.
          </div>
        </div>
      </section>
    </div>
  </div>

  <div id="lightbox" class="rev-lightbox" style="display:none;">
    <img id="lightboxImg" src="" alt="Review" />
  </div>
</AdminLayout>

<style is:global>
  .rev-page-shell { display:flex; flex-direction:column; gap:12px; }
  .rev-page-header {
    display:flex; align-items:flex-start; justify-content:space-between;
    gap:16px; flex-wrap:wrap;
  }
  .rev-page-actions { display:flex; gap:10px; flex-wrap:wrap; }
  .rev-action-control {
    display:inline-flex; align-items:center; gap:8px;
    background:var(--color-surface, #fff); border:1px solid var(--color-border, #e2e8f0);
    border-radius:10px; padding:8px 12px; color:var(--color-text-muted, #64748b);
    cursor:pointer;
  }
  .rev-inline-input, .rev-inline-select {
    border:none; background:transparent; color:var(--color-text, #0f172a);
    font:inherit; outline:none; cursor:pointer;
  }
  .rev-banner-card { border-left:4px solid var(--color-warning, #f59e0b); }

  .rev-grid {
    display:grid; grid-template-columns:minmax(300px, 380px) 1fr; gap:16px;
  }
  @media (max-width: 880px) { .rev-grid { grid-template-columns:1fr; } }

  .rev-dropzone {
    border:2px dashed var(--color-border, #cbd5e1); border-radius:14px;
    min-height:180px; display:flex; align-items:center; justify-content:center;
    text-align:center; cursor:pointer; padding:16px; margin-bottom:16px;
    transition:border-color .15s, background .15s;
  }
  .rev-dropzone:hover, .rev-dropzone.dragover {
    border-color:var(--color-primary, #6366f1);
    background:var(--color-primary-soft, rgba(99,102,241,.06));
  }
  .rev-drop-prompt { display:flex; flex-direction:column; align-items:center; gap:6px; color:var(--color-text-muted, #64748b); }
  .rev-drop-prompt small { font-size:.78rem; opacity:.8; }
  .rev-preview { max-width:100%; max-height:260px; border-radius:10px; object-fit:contain; }

  .rev-optional { color:var(--color-text-muted, #94a3b8); font-weight:400; font-size:.82em; }
  .rev-upload-footer { display:flex; align-items:center; gap:12px; margin-top:6px; }
  .rev-inline-msg { font-size:.85rem; }
  .rev-inline-msg.success { color:var(--color-success, #16a34a); }
  .rev-inline-msg.error { color:var(--color-danger, #dc2626); }

  .rev-count-pill {
    align-self:center; background:var(--color-primary-soft, rgba(99,102,241,.12));
    color:var(--color-primary, #4f46e5); border-radius:999px; padding:4px 12px;
    font-size:.82rem; font-weight:600; white-space:nowrap;
  }

  .rev-gallery-grid {
    display:grid; grid-template-columns:repeat(auto-fill, minmax(160px, 1fr)); gap:14px;
  }
  .rev-tile {
    border:1px solid var(--color-border, #e2e8f0); border-radius:12px; overflow:hidden;
    display:flex; flex-direction:column; background:var(--color-surface, #fff);
  }
  .rev-tile-img {
    width:100%; aspect-ratio:1/1; object-fit:cover; cursor:zoom-in;
    background:var(--color-surface-muted, #f1f5f9);
  }
  .rev-tile-body { padding:10px 12px; display:flex; flex-direction:column; gap:4px; }
  .rev-tile-date { font-size:.78rem; color:var(--color-text-muted, #64748b); }
  .rev-tile-reviewer { font-size:.85rem; font-weight:600; color:var(--color-text, #0f172a); }
  .rev-tile-stars { font-size:.8rem; color:#f59e0b; letter-spacing:1px; }
  .rev-tile-notes { font-size:.78rem; color:var(--color-text-muted, #64748b); }
  .rev-tile-actions { margin-top:6px; }
  .rev-tile-delete {
    border:none; background:transparent; color:var(--color-danger, #dc2626);
    font-size:.78rem; cursor:pointer; padding:0;
  }
  .rev-tile-delete:hover { text-decoration:underline; }

  .rev-empty { text-align:center; color:var(--color-text-muted, #94a3b8); padding:30px 10px; }

  .rev-lightbox {
    position:fixed; inset:0; background:rgba(0,0,0,.8); z-index:1000;
    display:grid; place-items:center; padding:24px; cursor:zoom-out;
  }
  .rev-lightbox img { max-width:min(92vw, 900px); max-height:90vh; border-radius:10px; }
</style>

<script>
  const API = import.meta.env.PUBLIC_API_URL;
  const token = localStorage.getItem("token");

  const monthPicker = document.getElementById("monthPicker");
  const staffPicker = document.getElementById("staffPicker");
  const staffPickerWrap = document.getElementById("staffPickerWrap");
  const fileInput = document.getElementById("fileInput");
  const dropzone = document.getElementById("dropzone");
  const previewImg = document.getElementById("previewImg");
  const dropPrompt = document.getElementById("dropPrompt");
  const uploadBtn = document.getElementById("uploadBtn");

  let isAdmin = false;
  let selectedFile = null;

  function parseJwtPayload(rawToken) {
    try {
      const segment = rawToken?.split(".")?.[1];
      if (!segment) return {};
      const normalized = segment
        .replaceAll("-", "+")
        .replaceAll("_", "/")
        .padEnd(Math.ceil(segment.length / 4) * 4, "=");
      return JSON.parse(atob(normalized));
    } catch {
      return {};
    }
  }

  function escapeHtml(value) {
    return String(value ?? "")
      .replaceAll("&", "&amp;")
      .replaceAll("<", "&lt;")
      .replaceAll(">", "&gt;")
      .replaceAll('"', "&quot;")
      .replaceAll("'", "&#39;");
  }

  function setMonthDefault() {
    const now = new Date();
    monthPicker.value = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, "0")}`;
  }

  function selectedYearMonth() {
    const [year, month] = (monthPicker.value || "").split("-").map(Number);
    return { year, month };
  }

  function monthLabel() {
    const { year, month } = selectedYearMonth();
    if (!year || !month) return "this month";
    return new Date(year, month - 1, 1).toLocaleDateString(undefined, { month: "long", year: "numeric" });
  }

  function formatDate(iso) {
    if (!iso) return "";
    const d = new Date(iso);
    if (isNaN(d.getTime())) return "";
    return d.toLocaleDateString(undefined, { year: "numeric", month: "short", day: "numeric" });
  }

  function showBanner(message) {
    const banner = document.getElementById("revBanner");
    document.getElementById("revBannerText").textContent = message;
    banner.style.display = message ? "" : "none";
  }

  async function loadRole() {
    const payload = parseJwtPayload(token);
    const role = (
      payload["http://schemas.microsoft.com/ws/2008/06/identity/claims/role"] ||
      payload.role ||
      ""
    ).toLowerCase();
    isAdmin = role === "admin";
    staffPickerWrap.style.display = isAdmin ? "" : "none";
    if (isAdmin) await loadReceptionists();
  }

  // Reuse the KPI dashboard endpoint to enumerate receptionists for the admin picker.
  async function loadReceptionists() {
    try {
      const { year, month } = selectedYearMonth();
      const res = await fetch(`${API}/api/receptionist-kpi/dashboard?year=${year}&month=${month}`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      const data = await res.json().catch(() => ({}));
      if (!res.ok) return;
      const list = data.receptionists || [];
      const current = staffPicker.value;
      staffPicker.innerHTML = list
        .map((s) => `<option value="${escapeHtml(s.id)}">${escapeHtml(s.name)}</option>`)
        .join("");
      if (current && list.some((s) => s.id === current)) staffPicker.value = current;
    } catch { /* ignore */ }
  }

  function currentStaffId() {
    return isAdmin && staffPicker.value ? staffPicker.value : null;
  }

  function setSelectedFile(file) {
    selectedFile = file || null;
    if (selectedFile) {
      previewImg.src = URL.createObjectURL(selectedFile);
      previewImg.style.display = "";
      dropPrompt.style.display = "none";
    } else {
      previewImg.removeAttribute("src");
      previewImg.style.display = "none";
      dropPrompt.style.display = "";
    }
    uploadBtn.disabled = !selectedFile;
  }

  function wireDropzone() {
    dropzone.addEventListener("click", () => fileInput.click());
    fileInput.addEventListener("change", () => setSelectedFile(fileInput.files?.[0] || null));
    ["dragenter", "dragover"].forEach((evt) =>
      dropzone.addEventListener(evt, (e) => { e.preventDefault(); dropzone.classList.add("dragover"); }));
    ["dragleave", "drop"].forEach((evt) =>
      dropzone.addEventListener(evt, (e) => { e.preventDefault(); dropzone.classList.remove("dragover"); }));
    dropzone.addEventListener("drop", (e) => {
      const file = e.dataTransfer?.files?.[0];
      if (file) setSelectedFile(file);
    });
  }

  async function uploadReview() {
    if (!selectedFile) return;
    const ok = document.getElementById("uploadMsg");
    const err = document.getElementById("uploadErr");
    ok.style.display = "none";
    err.style.display = "none";
    uploadBtn.disabled = true;

    try {
      const { year, month } = selectedYearMonth();
      if (!year || !month) throw new Error("Pick a month first.");

      const fd = new FormData();
      fd.append("file", selectedFile, selectedFile.name);
      fd.append("year", String(year));
      fd.append("month", String(month));
      const staffId = currentStaffId();
      if (staffId) fd.append("staffId", staffId);
      const reviewerName = document.getElementById("reviewerNameInput").value.trim();
      if (reviewerName) fd.append("reviewerName", reviewerName);
      const rating = document.getElementById("ratingInput").value;
      if (rating) fd.append("rating", rating);
      const notes = document.getElementById("notesInput").value.trim();
      if (notes) fd.append("notes", notes);

      const res = await fetch(`${API}/api/review-uploads`, {
        method: "POST",
        headers: { Authorization: `Bearer ${token}` },
        body: fd,
      });
      const data = await res.json().catch(() => ({}));
      if (!res.ok) throw new Error(data.message || `Upload failed (HTTP ${res.status})`);

      ok.style.display = "";
      setTimeout(() => { ok.style.display = "none"; }, 2000);
      // Reset the form.
      setSelectedFile(null);
      fileInput.value = "";
      document.getElementById("reviewerNameInput").value = "";
      document.getElementById("ratingInput").value = "";
      document.getElementById("notesInput").value = "";
      await loadGallery();
    } catch (error) {
      err.textContent = error.message || "Upload failed.";
      err.style.display = "";
    } finally {
      uploadBtn.disabled = !selectedFile;
    }
  }

  async function loadGallery() {
    const { year, month } = selectedYearMonth();
    if (!year || !month) return;
    document.getElementById("galleryMonthLabel").textContent = monthLabel();
    document.getElementById("uploadMonthLabel").textContent = monthLabel();

    const params = new URLSearchParams({ year: String(year), month: String(month) });
    const staffId = currentStaffId();
    if (staffId) params.set("staffId", staffId);

    try {
      const res = await fetch(`${API}/api/review-uploads?${params.toString()}`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      const data = await res.json().catch(() => ({}));
      if (!res.ok) throw new Error(data.message || `Failed to load reviews (${res.status})`);
      renderGallery(data);
    } catch (error) {
      showBanner(error.message || "Failed to load reviews.");
    }
  }

  function renderGallery(data) {
    const grid = document.getElementById("galleryGrid");
    const empty = document.getElementById("galleryEmpty");
    const items = data.items || [];
    document.getElementById("galleryCount").textContent = String(data.count ?? items.length);

    if (items.length === 0) {
      grid.innerHTML = "";
      empty.style.display = "";
      return;
    }
    empty.style.display = "none";

    grid.innerHTML = items.map((item) => {
      const stars = item.rating ? "★".repeat(item.rating) + "☆".repeat(5 - item.rating) : "";
      return `
        <div class="rev-tile">
          <img class="rev-tile-img" src="${escapeHtml(item.imageUrl)}" alt="Review" loading="lazy" data-full="${escapeHtml(item.imageUrl)}" />
          <div class="rev-tile-body">
            <div class="rev-tile-date">Added ${escapeHtml(formatDate(item.uploadedAt))}</div>
            ${item.reviewerName ? `<div class="rev-tile-reviewer">${escapeHtml(item.reviewerName)}</div>` : ""}
            ${stars ? `<div class="rev-tile-stars">${stars}</div>` : ""}
            ${item.notes ? `<div class="rev-tile-notes">${escapeHtml(item.notes)}</div>` : ""}
            <div class="rev-tile-actions">
              <button type="button" class="rev-tile-delete" data-delete-id="${escapeHtml(item.id)}">Delete</button>
            </div>
          </div>
        </div>`;
    }).join("");

    grid.querySelectorAll("[data-full]").forEach((img) =>
      img.addEventListener("click", () => openLightbox(img.dataset.full)));
    grid.querySelectorAll("[data-delete-id]").forEach((btn) =>
      btn.addEventListener("click", () => deleteReview(btn.dataset.deleteId)));
  }

  async function deleteReview(id) {
    if (!id) return;
    if (!confirm("Delete this review upload? This cannot be undone.")) return;
    try {
      const res = await fetch(`${API}/api/review-uploads/${id}`, {
        method: "DELETE",
        headers: { Authorization: `Bearer ${token}` },
      });
      if (!res.ok && res.status !== 204) {
        const data = await res.json().catch(() => ({}));
        throw new Error(data.message || `Delete failed (${res.status})`);
      }
      await loadGallery();
    } catch (error) {
      showBanner(error.message || "Delete failed.");
    }
  }

  function openLightbox(url) {
    const box = document.getElementById("lightbox");
    document.getElementById("lightboxImg").src = url;
    box.style.display = "grid";
  }
  document.getElementById("lightbox").addEventListener("click", (e) => {
    e.currentTarget.style.display = "none";
    document.getElementById("lightboxImg").removeAttribute("src");
  });

  monthPicker.addEventListener("change", async () => {
    if (isAdmin) await loadReceptionists();
    await loadGallery();
  });
  staffPicker.addEventListener("change", loadGallery);
  uploadBtn.addEventListener("click", uploadReview);

  setMonthDefault();
  wireDropzone();

  (async function init() {
    try {
      await loadRole();
      await loadGallery();
    } catch (error) {
      showBanner(error.message || "Failed to load review uploads page.");
    }
  })();
</script>
